<?php require_once __DIR__.'/../lib/bootstrap.php'; requestMethod('POST'); requireCsrf(); $d=requestJson(8000); $first=trim((string)($d['firstName']??'')); $last=trim((string)($d['lastName']??'')); $email=strtolower(trim((string)($d['email']??''))); $password=(string)($d['password']??''); $namePattern="/^[A-ZÁÉÍÓÚÜÑ][A-Za-zÁÉÍÓÚÜÑáéíóúüñ' -]*$/u"; if(!preg_match($namePattern,$first)||!preg_match($namePattern,$last)) apiRespond(['error'=>'El nombre y los apellidos deben empezar por mayúscula.'],422); if(!preg_match('/^[^\s@]+@[^\s@]+\.com$/i',$email)) apiRespond(['error'=>'El correo debe contener @ y terminar en .com.'],422); if(!preg_match('/^[A-ZÁÉÍÓÚÜÑ](?=.*\d).{5,}$/u',$password)) apiRespond(['error'=>'La contraseña debe empezar por mayúscula, tener al menos 6 caracteres y contener un número.'],422); if(db()->findUserByEmail($email)) apiRespond(['error'=>'Ya existe una cuenta con ese correo.'],409); $u=db()->createUser($first,$last,$email,password_hash($password,PASSWORD_DEFAULT)); session_regenerate_id(true); $_SESSION['user_id']=(int)$u['id']; $_SESSION['role']='cliente'; $_SESSION['csrf_token']=bin2hex(random_bytes(32)); $token=(string)$_SESSION['csrf_token']; db()->addEvent('user.registered',(int)$u['id'],null,null,['role'=>'cliente']); db()->addEvent('user.logged_in',(int)$u['id'],null,null,['role'=>'cliente']); apiRespond(['ok'=>true,'csrfToken'=>$token,'user'=>['id'=>(int)$u['id'],'firstName'=>$u['nombre'],'lastName'=>$u['apellidos'],'email'=>$u['email'],'role'=>$u['rol']]],201);
